import { io } from 'socket.io-client';

class SocketService {
  constructor() {
    this.socket = null;
    this.isConnected = false;
    this.reconnectAttempts = 0;
    this.maxReconnectAttempts = 5;
    this.reconnectInterval = 1000;
    this.listeners = new Map();
  }

  // Initialize socket connection
  connect(url = process.env.REACT_APP_SOCKET_URL || 'http://localhost:5000') {
    if (this.socket && this.socket.connected) {
      console.log('Socket already connected');
      return this.socket;
    }

    console.log('🔌 Connecting to socket server...');

    this.socket = io(url, {
      transports: ['websocket', 'polling'],
      autoConnect: true,
      reconnection: true,
      reconnectionAttempts: this.maxReconnectAttempts,
      reconnectionDelay: this.reconnectInterval,
      reconnectionDelayMax: 5000,
      timeout: 20000,
      forceNew: true,
    });

    this.setupEventListeners();
    return this.socket;
  }

  // Setup default event listeners
  setupEventListeners() {
    if (!this.socket) return;

    this.socket.on('connect', () => {
      console.log('✅ Socket connected:', this.socket.id);
      this.isConnected = true;
      this.reconnectAttempts = 0;
      this.emit('connection-status', { status: 'connected', socketId: this.socket.id });
    });

    this.socket.on('disconnect', (reason) => {
      console.log('❌ Socket disconnected:', reason);
      this.isConnected = false;
      this.emit('connection-status', { status: 'disconnected', reason });
    });

    this.socket.on('connect_error', (error) => {
      console.error('🔴 Socket connection error:', error);
      this.isConnected = false;
      this.reconnectAttempts++;
      this.emit('connection-status', { 
        status: 'error', 
        error: error.message,
        attempt: this.reconnectAttempts 
      });
    });

    this.socket.on('reconnect', (attemptNumber) => {
      console.log('🔄 Socket reconnected after', attemptNumber, 'attempts');
      this.isConnected = true;
      this.reconnectAttempts = 0;
      this.emit('connection-status', { status: 'reconnected', attempts: attemptNumber });
    });

    this.socket.on('reconnect_attempt', (attemptNumber) => {
      console.log('🔄 Socket reconnection attempt:', attemptNumber);
      this.emit('connection-status', { status: 'reconnecting', attempt: attemptNumber });
    });

    this.socket.on('reconnect_error', (error) => {
      console.error('🔴 Socket reconnection error:', error);
      this.emit('connection-status', { status: 'reconnect-error', error: error.message });
    });

    this.socket.on('reconnect_failed', () => {
      console.error('💥 Socket reconnection failed');
      this.isConnected = false;
      this.emit('connection-status', { status: 'reconnect-failed' });
    });

    // Handle real-time events
    this.socket.on('cart-updated', (data) => {
      console.log('🛒 Cart updated:', data);
      this.emit('cart-updated', data);
    });

    this.socket.on('order-created', (data) => {
      console.log('📦 Order created:', data);
      this.emit('order-created', data);
    });

    this.socket.on('order-updated', (data) => {
      console.log('📦 Order updated:', data);
      this.emit('order-updated', data);
    });

    this.socket.on('stock-updated', (data) => {
      console.log('📊 Stock updated:', data);
      this.emit('stock-updated', data);
    });

    this.socket.on('payment-status', (data) => {
      console.log('💳 Payment status:', data);
      this.emit('payment-status', data);
    });
  }

  // Join a room
  joinRoom(roomId) {
    if (this.socket && this.isConnected) {
      this.socket.emit('join-room', roomId);
      console.log(`📡 Joined room: ${roomId}`);
    }
  }

  // Leave a room
  leaveRoom(roomId) {
    if (this.socket && this.isConnected) {
      this.socket.emit('leave-room', roomId);
      console.log(`📡 Left room: ${roomId}`);
    }
  }

  // Join session room
  joinSession(sessionId) {
    if (this.socket && this.isConnected) {
      this.socket.emit('join-session', sessionId);
      console.log(`👤 Joined session: ${sessionId}`);
    }
  }

  // Subscribe to stock updates for a product
  subscribeToStock(productId) {
    if (this.socket && this.isConnected) {
      this.socket.emit('subscribe-stock', productId);
      console.log(`📊 Subscribed to stock updates for product: ${productId}`);
    }
  }

  // Unsubscribe from stock updates for a product
  unsubscribeFromStock(productId) {
    if (this.socket && this.isConnected) {
      this.socket.emit('unsubscribe-stock', productId);
      console.log(`📊 Unsubscribed from stock updates for product: ${productId}`);
    }
  }

  // Send a message
  emit(event, data) {
    if (this.socket && this.isConnected) {
      this.socket.emit(event, data);
    } else {
      console.warn(`Cannot emit ${event}: Socket not connected`);
    }
  }

  // Listen to events
  on(event, callback) {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, []);
    }
    this.listeners.get(event).push(callback);

    if (this.socket) {
      this.socket.on(event, callback);
    }
  }

  // Remove event listener
  off(event, callback) {
    if (this.socket) {
      this.socket.off(event, callback);
    }

    if (this.listeners.has(event)) {
      const callbacks = this.listeners.get(event);
      const index = callbacks.indexOf(callback);
      if (index > -1) {
        callbacks.splice(index, 1);
      }
    }
  }

  // Remove all listeners for an event
  removeAllListeners(event) {
    if (this.socket) {
      this.socket.removeAllListeners(event);
    }
    
    if (event) {
      this.listeners.delete(event);
    } else {
      this.listeners.clear();
    }
  }

  // Disconnect socket
  disconnect() {
    if (this.socket) {
      console.log('🔌 Disconnecting socket...');
      this.socket.disconnect();
      this.socket = null;
      this.isConnected = false;
      this.listeners.clear();
    }
  }

  // Get connection status
  getConnectionStatus() {
    return {
      isConnected: this.isConnected,
      socketId: this.socket?.id || null,
      reconnectAttempts: this.reconnectAttempts,
    };
  }

  // Check if socket is connected
  isSocketConnected() {
    return this.socket && this.socket.connected && this.isConnected;
  }

  // Force reconnection
  forceReconnect() {
    if (this.socket) {
      this.socket.disconnect();
      setTimeout(() => {
        this.socket.connect();
      }, 1000);
    }
  }

  // Get socket instance
  getSocket() {
    return this.socket;
  }
}

// Create singleton instance
const socketService = new SocketService();

export default socketService;
